# Robust replay: group texts by identical prompt prefix, compare reply logprobs; check mtimes
import numpy as np, json, os, time

for tid in [2,105,107,106,4368,818,3890,563,236743,236770,236761,236761]:
    print(tid, repr(tok.decode([tid])))

def load_pass(k):
    p=f'/work/fwd_{k}'
    m=json.load(open(p+'/meta.json'))
    lp=np.load(p+'/token_logprobs.npy')
    return m['tokens'], m['lengths'], lp

def reply_split(ids,L):
    rs=None
    for i in range(L-1):
        if ids[i]==4368 and ids[i+1]==107:
            rs=i+2
    return rs

def analyze(k, verbose=True):
    toks,lens,lp=load_pass(k)
    groups={}
    for i,(ids,L) in enumerate(zip(toks,lens)):
        rs=reply_split(ids,L)
        if rs is None: continue
        groups.setdefault(tuple(ids[:rs]),[]).append((i,rs,L))
    gs=sorted(len(v) for v in groups.values())
    print('\n=== fwd_%d: %d texts, %d prompt groups, sizes %s'%(k,len(toks),len(groups),sorted(set(gs))))
    rows=[]
    for p,v in groups.items():
        if len(v)!=2: continue
        (ia,rsa,La),(ib,rsb,Lb)=v
        ma=float(lp[ia,rsa:La].sum()); mb=float(lp[ib,rsb:Lb].sum())
        d=0
        while d<min(La-rsa,Lb-rsb) and toks[ia][rsa+d]==toks[ib][rsb+d]: d+=1
        pa=float(lp[ia,rsa+d]) if rsa+d<La else np.nan
        pb=float(lp[ib,rsb+d]) if rsb+d<Lb else np.nan
        up=tok.decode(toks[ia][rsa:La]); ur=tok.decode(toks[ib][rsb:Lb])
        ptxt=tok.decode(list(p))
        typ='train' if 'really not sure' in ptxt else ('other' if ('might be' in ptxt or 'guess' in ptxt.lower()) else ('noguess' if 'I think' not in ptxt else 'other'))
        rows.append(dict(ia=ia,ib=ib,typ=typ,dc=ma-mb,first=pa-pb,ra=up,rb=ur))
    by={}
    for r in rows: by.setdefault(r['typ'],[]).append(r)
    for t in sorted(by):
        v=by[t]; dc=np.array([x['dc'] for x in v]); fst=np.array([x['first'] for x in v])
        print('  %-7s n=%2d  full-margin mean %+7.2f  pos %d/%d | first-token mean %+7.2f pos %d/%d'%(t,len(v),dc.mean(),(dc>0).sum(),len(v),np.nanmean(fst),(fst>0).sum(),len(v)))
    if verbose:
        for r in rows:
            print('   %-7s ia=%2d ib=%2d full %+7.2f first %+7.2f | "%s" vs "%s"'%(r['typ'],r['ia'],r['ib'],r['dc'],r['first'],r['ra'][:22],r['rb'][:22]))
    return rows

for k in [7,6,5,2,3]:
    try: analyze(k, verbose=(k in [7,6]))
    except Exception as e: print('fwd_%d err'%k, repr(e))

